import base64,json,pathlib,tempfile,subprocess,sys,shlex
files=json.loads(base64.b64decode(''))
commands=[('python -c "import sys, pypdf; print(sys.version.split()[0]); print(pypdf.__version__)"', 0), ('python make_sample.py', 0), ('python make_sample.py', 1), ('python check38.py snapshot', 0), ('python pdfkit.py count sample/contract.pdf sample/invoice.pdf sample/notes.pdf', 0), ('python pdfkit.py merge sample/merged.pdf sample/contract.pdf sample/invoice.pdf sample/notes.pdf', 0), ('python pdfkit.py split sample/merged.pdf sample/first.pdf 1-2', 0), ('python pdfkit.py rotate sample/notes.pdf sample/rotated.pdf 90', 0), ('python check38.py verify', 0), ('python pdfkit.py merge sample/merged.pdf sample/contract.pdf sample/invoice.pdf sample/notes.pdf', 1), ('python check38.py verify', 0), ('python -m unittest -v', 0)]
with tempfile.TemporaryDirectory(prefix='lesson38-record-') as d:
 root=pathlib.Path(d)
 for name,text in files.items():(root/name).write_text(text,encoding='utf-8')
 for command,expected in commands:
  print('\n### CMD: '+command,flush=True)
  args=shlex.split(command)
  if args[0]=='python':args[0]=sys.executable
  before=None
  if 'merge sample/merged.pdf' in command and (root/'sample'/'merged.pdf').exists():
   p=root/'sample'/'merged.pdf';before=(p.read_bytes(),p.stat().st_mtime_ns)
  result=subprocess.run(args,cwd=root,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,encoding='utf-8',errors='replace')
  print(result.stdout,end='',flush=True);print('### EXIT: '+str(result.returncode),flush=True)
  if result.returncode!=expected:raise SystemExit('Unexpected exit')
  if before is not None:assert before==(p.read_bytes(),p.stat().st_mtime_ns), 'Refused output changed'
